import json, pathlib
base = pathlib.Path('/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature/tests/php_oracle/drift/streams/php-8.5.6')
names = ["GLOB_ERR","GLOB_MARK","GLOB_NOCHECK","GLOB_NOSORT","GLOB_BRACE","GLOB_NOESCAPE","GLOB_ONLYDIR","GLOB_AVAILABLE_FLAGS"]
for target in sorted(p.name for p in base.iterdir() if p.is_dir()):
    f = base / target / 'streams-full.json'
    if not f.exists():
        continue
    data = json.loads(f.read_text())
    found = {}
    def walk(node):
        if isinstance(node, dict):
            sym = node.get('symbol')
            if sym in names:
                found[sym] = node.get('value', node.get('result'))
            for v in node.values():
                walk(v)
        elif isinstance(node, list):
            for v in node:
                walk(v)
    walk(data)
    print(target)
    for n in names:
        if n in found:
            print(f'    {n:24s} {found[n]}')
